import pandas as pd
import numpy as np
import re

train = pd.read_csv('/work/b3_pvk_open_train.csv')
pool = pd.read_csv('/work/b3_pvk_open_pool.csv')

def phys_score(row):
    s = 0.0
    notes = []
    c = row['composition']
    arch = row['architecture']
    etl = row['etl']
    htl = row['htl']
    bc = row['backcontact']
    dep = row['deposition']
    sub = row['substrate']

    # --- composition / bandgap / defect chemistry ---
    pb = 'Pb' in c
    sn = 'Sn' in c
    bi = 'Bi' in c
    sb = 'Sb' in c
    base = c.split('|')[0].strip()
    hetero = '|' in c

    if bi and not pb:
        s -= 8; notes.append('Pb-free Bi')
    elif sb and not pb:
        s -= 8; notes.append('Pb-free Sb')
    elif sn and not pb:
        s -= 6; notes.append('Sn-only oxidation')
    elif sn and pb:
        s += 2; notes.append('PbSn')
    elif pb:
        s += 6; notes.append('Pb')

    # A-site mixing: FA-based mixed cation is the high-efficiency family
    has_FA = 'FA' in c
    has_MA = 'MA' in c and 'FAMA' not in c or 'FAMA' in c or 'CsFAMA' in c or 'CsMA' in c
    # simpler
    fa = 'FA' in c
    ma = bool(re.search(r'(?<![A-Z])MA|(?:FAMA|CsMA|CsFAMA)', c))
    cs = 'Cs' in c
    br = 'Br' in c
    cl = 'Cl' in c

    if base in ['FAMAPbBrI','CsFAMAPbBrI']:
        s += 5; notes.append('triple/double mixed BrI')
    elif base in ['FAMAPbI','CsFAMAPbI','FAPbI','FAPbBrI']:
        s += 4.5; notes.append('FA-rich iodide')
    elif base in ['CsFAPbBrI','CsFAPbI']:
        s += 4; notes.append('CsFA')
    elif 'CsFAMAPbBrI' in base or 'FAMAPbBrI' in base:
        s += 4.5
    elif base in ['MAPbBrI','CsPbBrI','CsPbI','MAPbI']:
        s += 2
    elif 'PbBr' in c and 'I' not in c.replace('Bi',''):
        s -= 2; notes.append('wide-gap Br')
    elif 'PbCl' in c and 'I' not in c:
        s -= 4; notes.append('wide-gap Cl')

    # 2D-only vs 2D/3D hetero
    twod_markers = ['PEA','BA','BEA','EPA','ThMA','CHMA','BDA','IMMA','PDMA','AMP','Anyl','TFEA','EDA','oF','OA','HTAB']
    # BA as butylammonium vs BAMA - BAMAPbI is quasi-2D
    is_quasi2d = bool(re.match(r'^\((PEA|BA|BEA|EPA|ThMA|CHMA|BDA|IMMA|PDMA|AMP|Anyl|TFEA|EDA|oF|OA|HTAB|3AMP)', c)) or c.startswith('BA') or c.startswith('GU') or c.startswith('HA') or c.startswith('IM')
    if hetero and pb:
        s += 2.0; notes.append('2D/3D hetero passivation')
    elif is_quasi2d and not hetero:
        s -= 2.5; notes.append('quasi-2D low mobility')

    # --- architecture ---
    if arch=='nip':
        s += 1.0
    else:
        s += 0.5

    # --- ETL band alignment / selectivity ---
    if 'C60-SAM' in etl or 'PCBA' in etl:
        s += 3.5; notes.append('fullerene SAM ETL')
    elif 'SnO2-c | SnO2-np' in etl or 'SnO2-np | SnO2-c' in etl:
        s += 3.2; notes.append('bilayer SnO2')
    elif 'TiO2-c | TiO2-mp | SnO2' in etl or 'TiO2-c | SnO2' in etl:
        s += 3.3; notes.append('TiO2/SnO2 bilayer')
    elif re.search(r'SnO2-np \| (PEG|ImAc|PCBM|C9|KCl)', etl) or 'ImAcHcl' in etl or '| C9' in etl:
        s += 3.3; notes.append('SnO2 + passivation')
    elif 'SnO2-np' in etl or 'SnO2-c' in etl or 'SnO2-QDs' in etl:
        s += 2.8; notes.append('SnO2')
    elif 'TiO2-c | TiO2-mp' in etl and ('Trimethylamine' in etl or 'SrCl2' in etl or 'Li-TFSI' in etl or 'PCBM' in etl or 'CsPbCl' in etl):
        s += 3.0; notes.append('mp-TiO2 passivated')
    elif 'TiO2-c | TiO2-mp' in etl:
        s += 2.3; notes.append('mp-TiO2')
    elif 'TiO2-c | PCBA' in etl or 'TiO2-c | PCBM' in etl or 'TiO2-c | CsPb' in etl or 'TiO2-c | Thiourea' in etl:
        s += 2.8; notes.append('TiO2 + interface')
    elif 'TiO2-np' in etl or 'TiO2-c' in etl:
        s += 2.0; notes.append('compact TiO2')
    elif 'PCBM-60 | C60 | BCP' in etl or 'ICBA | C60 | BCP' in etl:
        s += 2.8; notes.append('PCBM/C60/BCP')
    elif 'C60 | BCP' in etl:
        s += 2.6; notes.append('C60/BCP')
    elif 'PCBM-60 | BCP' in etl:
        s += 2.4; notes.append('PCBM/BCP')
    elif 'PCBM' in etl and 'BCP' in etl:
        s += 2.3
    elif 'PCBM' in etl or 'C60' in etl:
        s += 1.8
    elif etl in ['TMAH','KY7F22-np','none']:
        s -= 2; notes.append('bad/non ETL')
    elif 'ZnO' in etl:
        s += 1.0; notes.append('ZnO FA-instability')
    elif 'Cr2O3' in etl or 'In2S3' in etl or 'Nb2O5' in etl:
        s += 0.8; notes.append('exotic ETL')
    else:
        s += 0.5; notes.append('other ETL')

    # --- HTL ---
    if '2PACz' in htl:
        s += 3.2; notes.append('SAM HTL 2PACz')
    elif 'PTAA' in htl and ('PFN' in htl or 'NiO' in htl):
        s += 3.2; notes.append('PTAA bilayer')
    elif htl=='PTAA' or htl.startswith('PTAA'):
        s += 2.7; notes.append('PTAA')
    elif 'CH3O-PEIA' in htl or 'OAI' in htl or 'HS-Ph-CN' in htl:
        s += 3.5; notes.append('passivated Spiro-like')
    elif 'CsPbBr3-np' in htl or 'CsPbCl3' in htl:
        s += 3.0; notes.append('QD interlayer HTL')
    elif 'Spiro-MeOTAD' in htl:
        s += 2.8; notes.append('Spiro')
    elif htl=='DM' or htl.endswith('| DM'):
        s += 2.6; notes.append('DM HTL (champ component)')
    elif 'NiO' in htl:
        s += 2.0; notes.append('NiO')
    elif 'CuSCN' in htl or 'CuI' in htl:
        s += 1.5
    elif 'P3HT' in htl:
        s += 1.2; notes.append('P3HT poor alignment/mobility')
    elif 'PEDOT' in htl:
        s += 0.5; notes.append('PEDOT acidic')
    elif htl=='none':
        s -= 0.5
    else:
        s += 1.3; notes.append('other HTL '+htl[:20])

    # architecture-HTL match
    if arch=='pin' and 'Spiro' in htl:
        s -= 1.5; notes.append('Spiro as bottom HTL in pin: solvent damage')
    if arch=='pin' and 'TiO2' in etl and 'mp' in etl:
        s -= 1.5; notes.append('high-T mp-TiO2 incompatible with pin')
    if arch=='nip' and 'PEDOT' in htl:
        s -= 1; notes.append('PEDOT as top HTL in nip unusual')

    # --- back contact chemistry ---
    if bc=='Au':
        s += 2.2; notes.append('Au inert')
    elif 'MoO3' in bc or 'MoOx' in bc:
        s += 2.0; notes.append('MoOx barrier')
    elif bc=='Cu' and arch=='pin':
        s += 2.2; notes.append('Cu inverted')
    elif bc=='Ag' and arch=='pin' and 'BCP' in etl:
        s += 1.6; notes.append('Ag + BCP')
    elif bc=='Ag' and arch=='nip':
        s += 1.0; notes.append('AgI risk in nip')
    elif bc=='Ag':
        s += 1.3
    elif 'Carbon' in bc:
        s += 0.3; notes.append('carbon Rs')
    elif 'Al' in bc:
        s -= 0.5; notes.append('Al corrosion')
    else:
        s += 0.8

    # --- substrate ---
    if 'PET' in sub or 'PEN' in sub or 'PDMS' in sub:
        s -= 2.0; notes.append('flexible')
    if 'FTO' in sub or 'ITO' in sub:
        s += 0.3

    # --- deposition / film quality ---
    if dep=='Spin-coating >> Spin-coating' or dep=='Spin-coating | Spin-coating':
        s += 0.8; notes.append('double spin')
    elif dep=='Spin-coating':
        s += 0.4
    elif 'Drop-infiltration' in dep:
        s -= 0.4
    elif 'Spray' in dep:
        s -= 0.6

    # synergies of complete stacks
    if arch=='nip' and 'Spiro' in htl and 'Au' in bc and pb and not sn:
        s += 0.8; notes.append('classic nip synergy')
    if arch=='pin' and 'PTAA' in htl and ('C60' in etl or 'PCBM' in etl) and pb:
        s += 0.8; notes.append('classic pin synergy')
    if 'C60-SAM' in etl and 'Spiro' in htl and 'Au' in bc:
        s += 1.2; notes.append('SAM-SnO2 championship stack')
    if hetero and 'Spiro' in htl and 'Au' in bc:
        s += 0.8; notes.append('2D/3D + spiro/Au')

    return s, '; '.join(notes)

scores = []
