import pandas as pd
import numpy as np
import re
from sklearn.model_selection import KFold

train = pd.read_csv('/work/b3_pvk_open_train.csv')
pool = pd.read_csv('/work/b3_pvk_open_pool.csv')

def family(c):
    base = c.split('|')[0].strip()
    base = re.sub(r'^\([^)]+\)','', base)
    # group
    if base in ['FAMAPbBrI','CsFAMAPbBrI']:
        return 'FAMA_mixed_halide'
    if base in ['FAMAPbI','CsFAMAPbI','FAPbI','CsFAPbI','FAPbBrI','CsFAPbBrI']:
        return 'FA_rich'
    if 'Sn' in c and 'Pb' in c:
        return 'PbSn'
    if 'Sn' in c:
        return 'Sn'
    if 'Bi' in c or 'Sb' in c:
        return 'BiSb'
    if base in ['MAPbBrI','MAPbI','CsPbI','CsPbBrI','CsMAPbI','CsMAPbBrI']:
        return 'MA_Cs_Pb'
    if 'PbBr' in c and 'I' not in base.replace('Bi',''):
        return 'wide_Br'
    if 'Pb' in c:
        return 'other_Pb'
    return 'other'

def stack_key(r):
    etl = r['etl']
    htl = r['htl']
    # coarsen
    if 'SnO2' in etl:
        e = 'SnO2'
        if 'SAM' in etl or 'PCBA' in etl or 'C9' in etl or 'ImAc' in etl or 'KCl' in etl or 'PEG' in etl:
            e = 'SnO2_pass'
        elif 'PCBM' in etl:
            e = 'SnO2_PCBM'
    elif 'TiO2' in etl and 'SnO2' in etl:
        e = 'TiO2_SnO2'
    elif 'TiO2-mp' in etl:
        e = 'TiO2mp'
        if 'TMAO' in etl or 'Trimethylamine' in etl or 'BaTiO' in etl or 'Li-TFSI' in etl:
            e = 'TiO2mp_pass'
    elif 'PCBA' in etl or 'SAM' in etl:
        e = 'SAM'
    elif 'C60' in etl and 'BCP' in etl:
        e = 'C60BCP'
    elif 'PCBM' in etl and 'BCP' in etl:
        e = 'PCBM_BCP'
    elif 'PCBM' in etl or 'C60' in etl:
        e = 'fullerene'
    elif 'ZnO' in etl:
        e = 'ZnO'
    else:
        e = 'otherETL'

    if 'Spiro' in htl:
        h = 'Spiro'
        if 'PEIA' in htl or 'OAI' in htl or 'HS-Ph' in htl or 'CsPb' in htl:
            h = 'Spiro_pass'
    elif 'PTAA' in htl:
        h = 'PTAA'
        if 'PFN' in htl or 'NiO' in htl:
            h = 'PTAA_bi'
    elif '2PACz' in htl:
        h = 'SAMHTL'
    elif 'NiO' in htl:
        h = 'NiO'
    elif 'PEDOT' in htl:
        h = 'PEDOT'
    elif htl=='none':
        h = 'none'
    else:
        h = 'otherHTL'

    if 'Au' in r['backcontact']:
        b = 'Au'
    elif 'MoO' in r['backcontact']:
        b = 'MoO_metal'
    elif r['backcontact']=='Cu':
        b = 'Cu'
    elif 'Ag' in r['backcontact']:
        b = 'Ag'
    elif 'Carbon' in r['backcontact']:
        b = 'Carbon'
    elif 'Al' in r['backcontact']:
        b = 'Al'
    else:
        b = 'otherBC'
    return r['architecture']+'|'+e+'|'+h+'|'+b

train = train.copy()
train['fam'] = train['composition'].map(family)
train['stack'] = train.apply(stack_key, axis=1)
print('Family means:')
print(train.groupby('fam')['target'].agg(['mean','median','count','max']).sort_values('mean',ascending=False).to_string())
print('\nStack means n>=3:')
g = train.groupby('stack')['target'].agg(['mean','median','count','max']).sort_values('mean',ascending=False)
print(g[g['count']>=3].to_string())

# Empirical Bayes combination
glob = train['target'].mean()
fam_stats = train.groupby('fam')['target'].agg(['mean','count'])
stack_stats = train.groupby('stack')['target'].agg(['mean','count'])

def eb(mean, n, m=glob, k=4):
    return (n*mean + k*m)/(n+k)

pool = pool.copy()
pool['fam'] = pool['composition'].map(family)
pool['stack'] = pool.apply(stack_key, axis=1)

preds = []
for _, r in pool.iterrows():
    fam = r['fam']
    st = r['stack']
    if fam in fam_stats.index:
        fm, fn = fam_stats.loc[fam]
        fpred = eb(fm, fn)
    else:
        fpred = glob
    if st in stack_stats.index:
        sm, sn = stack_stats.loc[st]
        spred = eb(sm, sn)
    else:
        spred = glob
    # additive: family + stack residual
    pred = fpred + (spred - glob)
    # bonuses
    c = r['composition']
    if '|' in c and 'Pb' in c:
        pred += 1.5  # 2D/3D
    if 'C60-SAM' in r['etl'] or 'PCBA' in r['etl']:
        pred += 1.5
    if 'PFN' in r['htl']:
        pred += 0.8
    if 'CsPbBr3-np' in r['htl']:
        pred += 1.0
    if 'PET' in r['substrate'] or 'PEN' in r['substrate']:
        pred -= 2.5
    if r['etl'] in ['TMAH','KY7F22-np']:
        pred -= 4
    if 'ZnO' in r['etl'] and 'FA' in c:
        pred -= 1.5  # FA/ZnO chemistry
    if r['architecture']=='pin' and 'Spiro' in r['htl']:
        pred -= 2
    if 'Spin-coating >> Spin-coating' in r['deposition'] or 'Spin-coating | Spin-coating' in r['deposition']:
        pred += 0.4
    preds.append(pred)

pool['pred'] = preds
print('\n=== TOP 20 EB ===')
cols = ['candidate_id','composition','architecture','etl','htl','backcontact','fam','stack','pred']
print(pool.sort_values('pred', ascending=False)[cols].head(20).to_string(index=False))
